<?php declare(strict_types=1);use StudPulse\Config;use StudPulse\Http\{Request,Router,ApiError};use StudPulse\Security\Auth;ini_set('display_errors','0');try{require dirname(__DIR__).'/app/bootstrap.php';}catch(\Throwable$error){Router::error($error);}$path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/';if(PHP_SAPI==='cli-server'&&$path!=='/'){$candidate=realpath(__DIR__.$path);if($candidate&&str_starts_with(strtolower($candidate),strtolower(__DIR__.DIRECTORY_SEPARATOR))&&is_file($candidate)&&!str_ends_with(strtolower($path),'.php')){return false;}}header('X-Content-Type-Options: nosniff');header('Referrer-Policy: no-referrer');header('X-Frame-Options: DENY');header('Permissions-Policy: camera=(self), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; connect-src 'self' https://tiles.openfreemap.org ".rtrim(Config::get('APP_BASE_URL'),'/')."; frame-src 'self' https://www.openstreetmap.org; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'");if(!Config::local()&&Config::get('APP_ENV')!==''){header('Strict-Transport-Security: max-age=31536000');}header('Cache-Control: no-store');if($path==='/health/live'){header('Content-Type: application/json');echo'{"status":"alive"}';exit;}$origin=$_SERVER['HTTP_ORIGIN']??'';if($origin!==''&&$origin===rtrim(Config::get('FRONTEND_ORIGIN'),'/')){header('Access-Control-Allow-Origin: '.$origin);header('Access-Control-Allow-Credentials: true');header('Vary: Origin');header('Access-Control-Expose-Headers: X-Request-ID, Retry-After, ETag');}if(($_SERVER['REQUEST_METHOD']??'GET')==='OPTIONS'){if($origin!==rtrim(Config::get('FRONTEND_ORIGIN'),'/')){http_response_code(403);exit;}header('Access-Control-Allow-Methods: GET, POST, PATCH, DELETE, OPTIONS');header('Access-Control-Allow-Headers: Content-Type, X-CSRF-Token, Idempotency-Key, Authorization, If-None-Match');http_response_code(204);exit;}if($path==='/runti